// and JSON codecs. They also support gzip compression.
func NewOrdersServiceHandler(svc OrdersServiceHandler, opts ...connect.HandlerOption) (string, http.Handler) {
	ordersServiceMethods := v1.File_orders_v1_orders_proto.Services().ByName("OrdersService").Methods()
	ordersServicePreviewOrderHandler := connect.NewUnaryHandler(
		OrdersServicePreviewOrderProcedure,
		svc.PreviewOrder,
		connect.WithSchema(ordersServiceMethods.ByName("PreviewOrder")),
		connect.WithHandlerOptions(opts...),
	)
	ordersServiceCreateOrderHandler := connect.NewUnaryHandler(
		OrdersServiceCreateOrderProcedure,
		svc.CreateOrder,
		connect.WithSchema(ordersServiceMethods.ByName("CreateOrder")),
		connect.WithHandlerOptions(opts...),
	)
	ordersServiceCancelOrderHandler := connect.NewUnaryHandler(
		OrdersServiceCancelOrderProcedure,
		svc.CancelOrder,
		connect.WithSchema(ordersServiceMethods.ByName("CancelOrder")),
		connect.WithHandlerOptions(opts...),
	)
	ordersServiceCancelAllOrdersHandler := connect.NewUnaryHandler(
		OrdersServiceCancelAllOrdersProcedure,
		svc.CancelAllOrders,
		connect.WithSchema(ordersServiceMethods.ByName("CancelAllOrders")),
		connect.WithHandlerOptions(opts...),
	)
	ordersServiceCancelAllAfterHandler := connect.NewUnaryHandler(
		OrdersServiceCancelAllAfterProcedure,
		svc.CancelAllAfter,
		connect.WithSchema(ordersServiceMethods.ByName("CancelAllAfter")),
		connect.WithHandlerOptions(opts...),
	)
	ordersServiceBatchCreateOrdersHandler := connect.NewUnaryHandler(
		OrdersServiceBatchCreateOrdersProcedure,
		svc.BatchCreateOrders,
		connect.WithSchema(ordersServiceMethods.ByName("BatchCreateOrders")),
		connect.WithHandlerOptions(opts...),
	)
	ordersServiceModifyOrderHandler := connect.NewUnaryHandler(
		OrdersServiceModifyOrderProcedure,
		svc.ModifyOrder,
		connect.WithSchema(ordersServiceMethods.ByName("ModifyOrder")),
		connect.WithHandlerOptions(opts...),
	)
	ordersServiceBatchReplaceOrdersHandler := connect.NewUnaryHandler(
		OrdersServiceBatchReplaceOrdersProcedure,
		svc.BatchReplaceOrders,
		connect.WithSchema(ordersServiceMethods.ByName("BatchReplaceOrders")),
		connect.WithHandlerOptions(opts...),
	)
	ordersServiceBatchCancelOrdersHandler := connect.NewUnaryHandler(
		OrdersServiceBatchCancelOrdersProcedure,
		svc.BatchCancelOrders,
		connect.WithSchema(ordersServiceMethods.ByName("BatchCancelOrders")),
		connect.WithHandlerOptions(opts...),
	)
	return "/orders.v1.OrdersService/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case OrdersServicePreviewOrderProcedure:
			ordersServicePreviewOrderHandler.ServeHTTP(w, r)
		case OrdersServiceCreateOrderProcedure:
			ordersServiceCreateOrderHandler.ServeHTTP(w, r)
		case OrdersServiceCancelOrderProcedure:
			ordersServiceCancelOrderHandler.ServeHTTP(w, r)
		case OrdersServiceCancelAllOrdersProcedure:
			ordersServiceCancelAllOrdersHandler.ServeHTTP(w, r)
		case OrdersServiceCancelAllAfterProcedure:
			ordersServiceCancelAllAfterHandler.ServeHTTP(w, r)
		case OrdersServiceBatchCreateOrdersProcedure:
			ordersServiceBatchCreateOrdersHandler.ServeHTTP(w, r)
		case OrdersServiceModifyOrderProcedure:
			ordersServiceModifyOrderHandler.ServeHTTP(w, r)
		case OrdersServiceBatchReplaceOrdersProcedure:
			ordersServiceBatchReplaceOrdersHandler.ServeHTTP(w, r)
		case OrdersServiceBatchCancelOrdersProcedure:
			ordersServiceBatchCancelOrdersHandler.ServeHTTP(w, r)
		default:
			http.NotFound(w, r)
		}
	})
}

